150			if edge.From == "" {
151				return nil, errInvalid(`lineage document edge is missing its upstream endpoint ("from")`)
152			}
153			if edge.To == "" {
154				return nil, errInvalid(`lineage document edge is missing its derived endpoint ("to")`)
155			}
156			if !nodes[edge.From] {
157				return nil, errInvalid("edge endpoint not listed in nodes: " + edge.From)
158			}
159			if !nodes[edge.To] {
