189	// decodeLineageDocument runs the document-level checks and returns the raw
190	// JSON values of the nodes and edges arrays: the text must be non-empty, valid
191	// UTF-8, exactly one complete JSON object with no duplicated object key, and
192	// both fields must be present as arrays (null rejected, element types are
193	// checked by the caller's typed unmarshal).
194	func decodeLineageDocument(text string) (json.RawMessage, json.RawMessage, error) {
195		if strings.TrimSpace(text) == "" {
196			return nil, nil, errInvalid("lineage document is empty: expected one JSON object with nodes and edges arrays")
197		}
198		// encoding/json silently rewrites invalid UTF-8 into U+FFFD instead of
199		// failing, and two byte-different names could then collapse into one, so
200		// the whole text is checked before anything is decoded.
201		if !utf8.ValidString(text) {
202			return nil, nil, errInvalid("lineage document is not valid UTF-8")
203		}
204		if err := rejectDuplicateKeys(text); err != nil {
205			return nil, nil, err
206		}
207	
208		var raw map[string]json.RawMessage
209		if err := json.Unmarshal([]byte(text), &raw); err != nil {
210			return nil, nil, errInvalid("lineage document must be one complete JSON object: " + err.Error())
211		}
212	
213		nodes, ok := raw["nodes"]
214		if !ok {
215			return nil, nil, errInvalid(`lineage document is missing the "nodes" array`)
216		}
217		edges, ok := raw["edges"]
218		if !ok {
219			return nil, nil, errInvalid(`lineage document is missing the "edges" array`)
220		}
221		if err := requireJSONArray(nodes, "nodes"); err != nil {
222			return nil, nil, err
223		}
224		if err := requireJSONArray(edges, "edges"); err != nil {
225			return nil, nil, err
226		}
227		return nodes, edges, nil
228	}
