230	// requireJSONArray rejects a field that is null or whose value is not a JSON
231	// array; element types inside the array are validated by typed unmarshalling.
232	func requireJSONArray(raw json.RawMessage, field string) error {
233		trimmed := strings.TrimSpace(string(raw))
234		switch {
235		case trimmed == "null":
236			return errInvalid("lineage document field " + field + " must be an array, got null")
237		case !strings.HasPrefix(trimmed, "["):
238			return errInvalid("lineage document field " + field + " must be an array")
239		}
240		return nil
241	}
