243	// decodeLineageName decodes one JSON string token (a node name or an edge
244	// endpoint) into its exact Go value, rejecting unpaired \u surrogate escapes
245	// before json.Unmarshal can touch the text.
246	//
247	// encoding/json accepts a lone \uD800–\uDFFF escape and rewrites it to the
248	// replacement character U+FFFD: two byte-different bad names would then
249	// collapse into one "�", and a bad edge endpoint would silently match a real
250	// dataset named "�". The raw token is therefore scanned first. A high
251	// surrogate escape is valid only when it is immediately followed by the low
252	// surrogate escape that together represent one character; a lone high, a lone
253	// low, a reversed pair, or a pair broken by other escapes or characters is
254	// unpaired. On success ok is true with the decoded value; when the token
255	// contains an unpaired escape, ok is still true, name is empty and badEscape
256	// holds the escape in its original \uXXXX spelling; ok is false only when the
257	// token is not a JSON string. The token was extracted from an already
258	// validated document, so json.Unmarshal cannot fail for a token that starts
259	// with a quote.
260	func decodeLineageName(raw json.RawMessage) (name, badEscape string, ok bool) {
261		if !strings.HasPrefix(strings.TrimSpace(string(raw)), `"`) {
262			return "", "", false
263		}
264		if bad := firstUnpairedSurrogate(string(raw)); bad != "" {
265			return "", bad, true
266		}
267		var decoded string
268		if err := json.Unmarshal(raw, &decoded); err != nil {
269			return "", "", false
270		}
271		return decoded, "", true
272	}
