274	// firstUnpairedSurrogate scans the raw text of one JSON string token and
275	// returns the first unpaired \u surrogate escape in its original spelling
276	// ("" when every surrogate escape is correctly paired). Escaped backslashes
277	// are skipped as a unit, so "\\ud800" is literal backslash-plus-letters, not a
278	// surrogate escape.
279	func firstUnpairedSurrogate(token string) string {
280		for i := 0; i < len(token); {
281			if token[i] != '\\' {
282				i++
283				continue
284			}
285			if i+1 >= len(token) {
286				i++
287				continue
288			}
289			switch token[i+1] {
290			case '\\':
291				// An escaped backslash consumes both characters; whatever follows
292				// is literal text, including a "\ud800"-looking sequence.
293				i += 2
294				continue
295			case 'u':
