323	// decodeJSONHexU decodes the \uXXXX escape beginning at token[pos] (token[pos]
324	// is a backslash and token[pos+1] the letter u) into its code point.
325	func decodeJSONHexU(token string, pos int) (rune, bool) {
326		if pos+6 > len(token) || token[pos] != '\\' || token[pos+1] != 'u' {
327			return 0, false
328		}
329		var r rune
330		for k := pos + 2; k < pos+6; k++ {
331			var digit rune
332			switch {
333			case token[k] >= '0' && token[k] <= '9':
334				digit = rune(token[k] - '0')
335			case token[k] >= 'a' && token[k] <= 'f':
336				digit = rune(token[k]-'a') + 10
337			case token[k] >= 'A' && token[k] <= 'F':
338				digit = rune(token[k]-'A') + 10
339			default:
340				return 0, false
341			}
